/* STM32CubeU5 HAL UART reception into a circular buffer by GPDMA linked-list mode.
 *
 * Unmodified HAL. USART1 at 115200 baud from PCLK2 = 160 MHz. GPDMA1 channel 3 serves the
 * USART1_RX request through a circular linked-list queue with one linear node, configured as
 * generated by STM32CubeMX (HAL_DMAEx_List_BuildNode, HAL_DMAEx_List_InsertNode,
 * HAL_DMAEx_List_SetCircularMode, HAL_DMAEx_List_Init, HAL_DMAEx_List_LinkQ).
 * HAL_UART_Receive_DMA starts reception into a 16-byte ring; the robot test writes 40 characters,
 * so the ring wraps and the half and full callbacks are counted. */

#include <string.h>

#include "clock_160mhz.h"

UART_HandleTypeDef huart1;
DMA_HandleTypeDef hdmaRx;
DMA_NodeTypeDef rxNode;
DMA_QListTypeDef rxQueue;

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t halfCount;
volatile uint32_t fullCount;
volatile uint32_t errorCount;
uint8_t rxRing[16];

static const char ready[] = "STM32U575 HAL UART circular DMA ready\r\n";

void SysTick_Handler(void)
{
    HAL_IncTick();
}

void GPDMA1_Channel3_IRQHandler(void)
{
    HAL_DMA_IRQHandler(&hdmaRx);
}

void USART1_IRQHandler(void)
{
    HAL_UART_IRQHandler(&huart1);
}

void HAL_UART_RxHalfCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart == &huart1)
    {
        halfCount++;
    }
}

void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    if (huart == &huart1)
    {
        fullCount++;
    }
}

void HAL_UART_ErrorCallback(UART_HandleTypeDef *huart)
{
    if (huart == &huart1)
    {
        errorCount++;
    }
}

static void check(HAL_StatusTypeDef status, uint32_t at)
{
    step = at;
    if (status != HAL_OK)
    {
        failedStep = at;
        for (;;)
        {
        }
    }
}

static void rxQueueConfig(void)
{
    DMA_NodeConfTypeDef node = {0};

    node.NodeType = DMA_GPDMA_LINEAR_NODE;
    node.Init.Request = GPDMA1_REQUEST_USART1_RX;
    node.Init.BlkHWRequest = DMA_BREQ_SINGLE_BURST;
    node.Init.Direction = DMA_PERIPH_TO_MEMORY;
    node.Init.SrcInc = DMA_SINC_FIXED;
    node.Init.DestInc = DMA_DINC_INCREMENTED;
    node.Init.SrcDataWidth = DMA_SRC_DATAWIDTH_BYTE;
    node.Init.DestDataWidth = DMA_DEST_DATAWIDTH_BYTE;
    node.Init.SrcBurstLength = 1;
    node.Init.DestBurstLength = 1;
    node.Init.TransferAllocatedPort = DMA_SRC_ALLOCATED_PORT0 | DMA_DEST_ALLOCATED_PORT1;
    node.Init.TransferEventMode = DMA_TCEM_BLOCK_TRANSFER;
    node.Init.Mode = DMA_NORMAL;
    node.TriggerConfig.TriggerPolarity = DMA_TRIG_POLARITY_MASKED;
    node.DataHandlingConfig.DataExchange = DMA_EXCHANGE_NONE;
    node.DataHandlingConfig.DataAlignment = DMA_DATA_RIGHTALIGN_ZEROPADDED;
    node.SrcAddress = 0;
    node.DstAddress = 0;
    node.DataSize = 0;
    check(HAL_DMAEx_List_BuildNode(&node, &rxNode), 100);
    check(HAL_DMAEx_List_InsertNode(&rxQueue, NULL, &rxNode), 101);
    check(HAL_DMAEx_List_SetCircularMode(&rxQueue), 102);

    hdmaRx.Instance = GPDMA1_Channel3;
    hdmaRx.InitLinkedList.Priority = DMA_LOW_PRIORITY_HIGH_WEIGHT;
    hdmaRx.InitLinkedList.LinkStepMode = DMA_LSM_FULL_EXECUTION;
    hdmaRx.InitLinkedList.LinkAllocatedPort = DMA_LINK_ALLOCATED_PORT0;
    hdmaRx.InitLinkedList.TransferEventMode = DMA_TCEM_BLOCK_TRANSFER;
    hdmaRx.InitLinkedList.LinkedListMode = DMA_LINKEDLIST_CIRCULAR;
    check(HAL_DMAEx_List_Init(&hdmaRx), 103);
    check(HAL_DMAEx_List_LinkQ(&hdmaRx, &rxQueue), 104);
}

void HAL_UART_MspInit(UART_HandleTypeDef *huart)
{
    if (huart->Instance != USART1)
    {
        return;
    }
    GPIO_InitTypeDef init = {0};

    __HAL_RCC_USART1_CLK_ENABLE();
    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_GPDMA1_CLK_ENABLE();

    /* PA9 TX, PA10 RX, AF7 (STM32U575 datasheet alternate function table). */
    init.Pin = GPIO_PIN_9 | GPIO_PIN_10;
    init.Mode = GPIO_MODE_AF_PP;
    init.Pull = GPIO_NOPULL;
    init.Speed = GPIO_SPEED_FREQ_LOW;
    init.Alternate = GPIO_AF7_USART1;
    HAL_GPIO_Init(GPIOA, &init);

    rxQueueConfig();
    __HAL_LINKDMA(huart, hdmarx, hdmaRx);

    HAL_NVIC_SetPriority(GPDMA1_Channel3_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(GPDMA1_Channel3_IRQn);
    HAL_NVIC_SetPriority(USART1_IRQn, 1, 0);
    HAL_NVIC_EnableIRQ(USART1_IRQn);
}

int main(void)
{
    check(HAL_Init(), 1);
    check(SystemClockConfig160MHz(), 2);

    huart1.Instance = USART1;
    huart1.Init.BaudRate = 115200;
    huart1.Init.WordLength = UART_WORDLENGTH_8B;
    huart1.Init.StopBits = UART_STOPBITS_1;
    huart1.Init.Parity = UART_PARITY_NONE;
    huart1.Init.Mode = UART_MODE_TX_RX;
    huart1.Init.HwFlowCtl = UART_HWCONTROL_NONE;
    huart1.Init.OverSampling = UART_OVERSAMPLING_16;
    huart1.Init.OneBitSampling = UART_ONE_BIT_SAMPLE_DISABLE;
    huart1.Init.ClockPrescaler = UART_PRESCALER_DIV1;
    huart1.AdvancedInit.AdvFeatureInit = UART_ADVFEATURE_NO_INIT;
    check(HAL_UART_Init(&huart1), 3);
    check(HAL_UARTEx_SetTxFifoThreshold(&huart1, UART_TXFIFO_THRESHOLD_1_8), 4);
    check(HAL_UARTEx_SetRxFifoThreshold(&huart1, UART_RXFIFO_THRESHOLD_1_8), 5);
    check(HAL_UARTEx_DisableFifoMode(&huart1), 6);

    check(HAL_UART_Receive_DMA(&huart1, rxRing, sizeof(rxRing)), 7);
    check(HAL_UART_Transmit(&huart1, (const uint8_t *)ready, strlen(ready), 100), 8);

    step = 9;
    for (;;)
    {
    }
}
